insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('cuanta-azucar-tomamos-sin-darnos-cuenta','agricultura',array['salud','ciencias']::text[],'¿Cuánta azúcar tomamos sin darnos cuenta?','Lee las etiquetas de alimentos y bebidas comunes, calcula cuánta azúcar tiene cada porción y compárala con recomendaciones públicas para descubrir dónde se esconde más.','Análisis','~12 h',12,array['Alimentación','Etiquetas']::text[],array['investigar','resolver']::text[],'propios',NULL,'nutricion ingenieria quimica ingenieria agroindustrial estadistica educacion comunicaciones medicina ingenieria industrial lectura de etiquetas. conversion de unidades. graficos. comunicacion clara. etiquetas de productos reales. hoja de calculo. un editor de infografias.',$g13sld${"id": "cuanta-azucar-tomamos-sin-darnos-cuenta", "area": "agricultura", "areas2": ["salud", "ciencias"], "titulo": "¿Cuánta azúcar tomamos sin darnos cuenta?", "resumen": "Lee las etiquetas de alimentos y bebidas comunes, calcula cuánta azúcar tiene cada porción y compárala con recomendaciones públicas para descubrir dónde se esconde más.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Alimentación", "Etiquetas"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Nutrición", "Ingeniería Química", "Ingeniería Agroindustrial", "Estadística", "Educación", "Comunicaciones", "Medicina", "Ingeniería Industrial"], "problema": ["El azúcar no está solo en los dulces: aparece en bebidas, salsas, cereales y productos que no parecen dulces, y las etiquetas la presentan con nombres y unidades que casi nadie convierte en algo imaginable.", "Por eso es difícil saber cuánta se toma en un día aunque se intente prestar atención."], "desarrollar": ["Elige entre quince y veinte productos de uso común, lee la etiqueta, convierte los gramos de azúcar por porción a cucharaditas y ordénalos de más a menos, anotando el tamaño real de la porción.", "Compara con la recomendación pública de organismos de salud, muestra los productos que más sorprenden y prepara una hoja o infografía clara que ayude a otros a leer una etiqueta."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara productos del mismo tipo de distintas marcas y descubre cuánto varían."}, {"titulo": "Otro formato", "aporta": "crea una calculadora sencilla en hoja de cálculo donde se escribe lo que se consume en un día de ejemplo."}, {"titulo": "Un paso más", "aporta": "diseña una tarjeta de bolsillo con los nombres con que el azúcar aparece en las etiquetas."}], "objetivos": ["Leer e interpretar etiquetas nutricionales.", "Convertir unidades a medidas cotidianas.", "Comparar productos y con una recomendación oficial.", "Explicar los hallazgos de forma clara."], "habilidades": ["Lectura de etiquetas.", "Conversión de unidades.", "Gráficos.", "Comunicación clara."], "herramientas": ["Etiquetas de productos reales.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["Cita la recomendación oficial que uses y no des consejos personalizados de dieta ni de salud.", "Habla de productos por categoría o con ejemplos neutros; no hagas afirmaciones sobre marcas que no puedas sustentar."], "otroSector": "La misma técnica sirve para analizar sal, grasas, aditivos o cualquier dato de una etiqueta de otro tipo de producto."}$g13sld$::jsonb,5),
('una-campana-para-tomar-menos-bebidas-azucaradas','agricultura',array['salud','arte']::text[],'Una campaña para tomar menos bebidas azucaradas','Diseña una campaña breve que ayude a una comunidad a tomar más agua y menos bebidas azucaradas, y comprueba con una pequeña prueba qué mensaje se entiende mejor.','Plan','~20 h',20,array['Campañas','Alimentación']::text[],array['crear','resolver']::text[],'ficticios',NULL,'comunicaciones publicidad diseno grafico nutricion psicologia educacion administracion medicina comunicacion persuasiva. diseno grafico basico. encuestas breves. planificacion. un editor de diseno o de presentaciones. un formulario anonimo. hoja de calculo.',$g14sld${"id": "una-campana-para-tomar-menos-bebidas-azucaradas", "area": "agricultura", "areas2": ["salud", "arte"], "titulo": "Una campaña para tomar menos bebidas azucaradas", "resumen": "Diseña una campaña breve que ayude a una comunidad a tomar más agua y menos bebidas azucaradas, y comprueba con una pequeña prueba qué mensaje se entiende mejor.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Campañas", "Alimentación"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Comunicaciones", "Publicidad", "Diseño Gráfico", "Nutrición", "Psicología", "Educación", "Administración", "Medicina"], "problema": ["Las bebidas azucaradas son baratas, están por todas partes y se asocian a momentos agradables. Las campañas que solo regañan o asustan suelen ser ignoradas.", "Los mensajes funcionan mejor cuando entienden por qué la gente toma esas bebidas y le ofrecen una alternativa fácil, no cuando la culpan."], "desarrollar": ["Elige un público concreto, como estudiantes o familias, y escribe tres mensajes distintos: uno informativo, uno cercano al día a día y uno basado en una alternativa fácil, como tener agua a mano.", "Diseña una pieza simple para cada mensaje, pide a algunas personas que ordenen cuál entienden y recuerdan más, y desarrolla el plan de la campaña a partir del mensaje que mejor funcione."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "adapta el mensaje a otro público, como adolescentes o adultos mayores."}, {"titulo": "Otro formato", "aporta": "conviértela en una serie corta de videos o imágenes."}, {"titulo": "Un paso más", "aporta": "propón cómo medir si la campaña cambió algo, por ejemplo con una pregunta antes y después."}], "objetivos": ["Elegir un público y un objetivo claros.", "Escribir mensajes distintos y compararlos.", "Probarlos con personas.", "Armar el plan de la campaña."], "habilidades": ["Comunicación persuasiva.", "Diseño gráfico básico.", "Encuestas breves.", "Planificación."], "herramientas": ["Un editor de diseño o de presentaciones.", "Un formulario anónimo.", "Hoja de cálculo."], "lineamientos": ["Evita mensajes que culpen, humillen o hablen del cuerpo de las personas: el foco es la bebida y la alternativa, no cómo se ve alguien.", "Basa los datos que uses en fuentes públicas oficiales y cítalas; no exageres cifras."], "otroSector": "La misma estructura sirve para campañas de reciclaje, de ahorro de energía, de seguridad vial o de cuidado del agua."}$g14sld$::jsonb,6),
('materiales-para-que-ninas-y-ninos-aprendan-habitos-saludables-jugando','educacion',array['salud','arte']::text[],'Materiales para que niñas y niños aprendan hábitos saludables jugando','Diseña un juego, una historia o una actividad que enseñe un hábito sencillo de cuidado a niñas y niños, y pruébalo con adultos antes de llevarlo a un grupo real.','Prototipo','~20 h',20,array['Niñez','Hábitos']::text[],array['crear','resolver']::text[],'ficticios',NULL,'educacion educacion inicial diseno grafico comunicaciones psicologia enfermeria trabajo social nutricion diseno de actividades. comunicacion para ninos. diseno grafico basico. evaluacion sencilla. papel, cartulina o un editor de diseno. un editor de documentos. una hoja de observacion.',$g15sld${"id": "materiales-para-que-ninas-y-ninos-aprendan-habitos-saludables-jugando", "area": "educacion", "areas2": ["salud", "arte"], "titulo": "Materiales para que niñas y niños aprendan hábitos saludables jugando", "resumen": "Diseña un juego, una historia o una actividad que enseñe un hábito sencillo de cuidado a niñas y niños, y pruébalo con adultos antes de llevarlo a un grupo real.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Niñez", "Hábitos"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Educación", "Educación Inicial", "Diseño Gráfico", "Comunicaciones", "Psicología", "Enfermería", "Trabajo Social", "Nutrición"], "problema": ["Los hábitos de cuidado, como lavarse las manos, dormir lo suficiente o beber agua, se aprenden mejor jugando que escuchando una lista. Muchos materiales para niños son largos, aburridos o con un tono de regaño.", "Lo que funciona con una edad no sirve para otra, así que un mismo material rara vez sirve para todos."], "desarrollar": ["Elige un hábito y un rango de edad, y diseña una actividad corta, como un juego de cartas, un cuento o una canción, con instrucciones claras para quien la dirija.", "Pruébala primero con adultos que hagan el papel de niños, ajusta lo que no se entienda o no divierta y deja una versión final con una guía breve para docentes o familiares."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "adapta el material a una edad distinta y compara qué cambió."}, {"titulo": "Otro formato", "aporta": "conviértelo en un material imprimible o en una actividad para el aula."}, {"titulo": "Un paso más", "aporta": "diseña una pequeña evaluación para ver si el material enseñó lo que quería."}], "objetivos": ["Elegir un hábito y un público por edad.", "Diseñar una actividad clara y atractiva.", "Probarla y mejorarla.", "Preparar una guía para quien la use."], "habilidades": ["Diseño de actividades.", "Comunicación para niños.", "Diseño gráfico básico.", "Evaluación sencilla."], "herramientas": ["Papel, cartulina o un editor de diseño.", "Un editor de documentos.", "Una hoja de observación."], "lineamientos": ["No lleves el material a niñas y niños sin permiso de sus responsables y de la institución, y no tomes fotos ni datos personales de ellos.", "Basa los contenidos de salud en fuentes oficiales y cítalas; el material enseña hábitos, no da indicaciones médicas."], "otroSector": "La misma idea sirve para enseñar seguridad vial, cuidado del ambiente, finanzas básicas o convivencia."}$g15sld$::jsonb,6),
('como-mejorar-la-ergonomia-de-un-espacio-de-estudio-o-de-trabajo','industria',array['salud','ciudades']::text[],'¿Cómo mejorar la ergonomía de un espacio de estudio o de trabajo?','Revisa cómo está organizado tu espacio de estudio o de trabajo, detecta qué lo hace incómodo y prepara una guía sencilla de ajustes de bajo costo.','Guía','~15 h',15,array['Ergonomía','Espacios']::text[],array['resolver','crear']::text[],'propios',NULL,'ingenieria industrial ingenieria mecanica arquitectura diseno grafico ingenieria de sistemas administracion medicina psicologia medicion. analisis de puestos de trabajo. diseno de mejoras. comunicacion clara. cinta metrica y fotos del espacio. hoja de calculo. recomendaciones publicas de seguridad y salud.',$g16sld${"id": "como-mejorar-la-ergonomia-de-un-espacio-de-estudio-o-de-trabajo", "area": "industria", "areas2": ["salud", "ciudades"], "titulo": "¿Cómo mejorar la ergonomía de un espacio de estudio o de trabajo?", "resumen": "Revisa cómo está organizado tu espacio de estudio o de trabajo, detecta qué lo hace incómodo y prepara una guía sencilla de ajustes de bajo costo.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Ergonomía", "Espacios"], "intencion": ["resolver", "crear"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Ingeniería Industrial", "Ingeniería Mecánica", "Arquitectura", "Diseño Gráfico", "Ingeniería de Sistemas", "Administración", "Medicina", "Psicología"], "problema": ["Pasamos muchas horas sentados frente a una pantalla o a un escritorio, y la altura de la silla, la posición de la pantalla o la luz casi nunca se ajustan a quien los usa. La incomodidad se vuelve costumbre.", "Muchas recomendaciones de ergonomía están escritas para oficinas y no sirven para una mesa de estudio en casa o un mostrador pequeño."], "desarrollar": ["Elige un espacio real, el tuyo o el de alguien cercano con permiso, y registra con fotos del espacio sin personas y con medidas simples las alturas, distancias y la iluminación, y cómo se siente quien lo usa al terminar la jornada.", "Compara con recomendaciones públicas de organismos de seguridad y salud en el trabajo y arma una guía de una página con cinco ajustes de bajo costo y cómo comprobar si funcionaron."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara dos tipos de espacio, como una mesa de estudio y un puesto de atención al público."}, {"titulo": "Otro formato", "aporta": "convierte la guía en una lista de revisión para imprimir y pegar en el lugar."}, {"titulo": "Un paso más", "aporta": "diseña un pequeño soporte o ajuste con materiales económicos y evalúa si ayuda."}], "objetivos": ["Medir y describir un espacio de estudio o trabajo.", "Identificar fuentes de incomodidad.", "Compararlas con recomendaciones oficiales.", "Proponer ajustes de bajo costo y verificarlos."], "habilidades": ["Medición.", "Análisis de puestos de trabajo.", "Diseño de mejoras.", "Comunicación clara."], "herramientas": ["Cinta métrica y fotos del espacio.", "Hoja de cálculo.", "Recomendaciones públicas de seguridad y salud."], "lineamientos": ["No diagnostiques dolores ni lesiones: registra solo molestias que la persona describa y recomienda consultar a un profesional si persisten.", "Si evalúas el espacio de otra persona, pide permiso y no publiques fotos con rostros ni datos personales."], "otroSector": "Sirve para mejorar puestos de una fábrica, un laboratorio, una cocina, una caja de atención o un taller."}$g16sld$::jsonb,1),
('que-dificultades-tiene-una-persona-mayor-para-cuidar-su-salud','sociedad',array['salud','educacion']::text[],'¿Qué dificultades tiene una persona mayor para cuidar su salud?','Conversa con personas mayores de confianza para descubrir qué les cuesta más al cuidar su salud, como entender indicaciones, sacar citas, recoger medicinas o trasladarse, y propón apoyos concretos.','Investigación','~20 h',20,array['Mayores','Acceso']::text[],array['investigar','resolver']::text[],'propios',NULL,'trabajo social sociologia psicologia enfermeria medicina administracion ingenieria de sistemas comunicaciones entrevista y escucha. analisis cualitativo. diseno de servicios. comunicacion clara. cuaderno de notas. hoja de calculo o tabla. un editor de documentos.',$g17sld${"id": "que-dificultades-tiene-una-persona-mayor-para-cuidar-su-salud", "area": "sociedad", "areas2": ["salud", "educacion"], "titulo": "¿Qué dificultades tiene una persona mayor para cuidar su salud?", "resumen": "Conversa con personas mayores de confianza para descubrir qué les cuesta más al cuidar su salud, como entender indicaciones, sacar citas, recoger medicinas o trasladarse, y propón apoyos concretos.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Mayores", "Acceso"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Enfermería", "Medicina", "Administración", "Ingeniería de Sistemas", "Comunicaciones"], "problema": ["Cuidar la salud en la vejez implica muchos trámites: pedir citas, entender indicaciones, recordar horarios, recoger medicinas y moverse hasta un servicio. Para quien tiene menos movilidad, menos vista o menos costumbre con la tecnología, cada paso puede ser un obstáculo.", "Esos obstáculos casi nunca se cuentan, y las soluciones se piensan sin preguntarles a quienes los viven."], "desarrollar": ["Conversa con tres o cuatro personas mayores de tu entorno, con su consentimiento, sobre qué pasos de cuidar su salud les resultan más difíciles, sin pedirles datos médicos, y toma notas anónimas.", "Agrupa lo que escuches en tres o cuatro obstáculos y propón para cada uno un apoyo sencillo, como una guía impresa, un recordatorio o una forma de acompañamiento, y presenta tu propuesta."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara lo que dicen las personas mayores con lo que perciben quienes las acompañan."}, {"titulo": "Otro formato", "aporta": "convierte los hallazgos en un mapa del recorrido típico con los puntos donde más se complica."}, {"titulo": "Un paso más", "aporta": "diseña una hoja clara y de letra grande que reúna lo que una persona mayor necesita saber para una consulta."}], "objetivos": ["Escuchar a personas mayores con respeto y sin invadir.", "Identificar obstáculos frecuentes.", "Agruparlos con criterio.", "Proponer apoyos sencillos."], "habilidades": ["Entrevista y escucha.", "Análisis cualitativo.", "Diseño de servicios.", "Comunicación clara."], "herramientas": ["Cuaderno de notas.", "Hoja de cálculo o tabla.", "Un editor de documentos."], "lineamientos": ["Explica el propósito, pide consentimiento y no registres nombres ni datos médicos; respeta si alguien no quiere hablar de algún tema.", "Presenta tus propuestas como ideas basadas en lo que escuchaste, sin prometer resultados."], "otroSector": "Sirve para entender las dificultades de cualquier grupo con un servicio, como migrantes, personas con discapacidad o jóvenes en su primer trámite."}$g17sld$::jsonb,4),
('como-influyen-las-redes-sociales-en-los-habitos-de-salud','sociedad',array['salud','educacion']::text[],'¿Cómo influyen las redes sociales en los hábitos de salud?','Estudia qué tipos de contenido de salud, ejercicio o alimentación circulan en redes sociales y cómo lo perciben las personas, para entender qué ayuda y qué confunde.','Análisis','~20 h',20,array['Redes sociales','Hábitos']::text[],array['investigar','resolver']::text[],'propios',NULL,'comunicaciones psicologia sociologia ingenieria de sistemas estadistica educacion medicina nutricion analisis de contenido. encuestas. analisis basico de datos. pensamiento critico. hoja de calculo. un formulario anonimo. capturas de publicaciones publicas sin datos personales.',$g18sld${"id": "como-influyen-las-redes-sociales-en-los-habitos-de-salud", "area": "sociedad", "areas2": ["salud", "educacion"], "titulo": "¿Cómo influyen las redes sociales en los hábitos de salud?", "resumen": "Estudia qué tipos de contenido de salud, ejercicio o alimentación circulan en redes sociales y cómo lo perciben las personas, para entender qué ayuda y qué confunde.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Redes sociales", "Hábitos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Comunicaciones", "Psicología", "Sociología", "Ingeniería de Sistemas", "Estadística", "Educación", "Medicina", "Nutrición"], "problema": ["Muchas personas aprenden o se comparan con lo que ven en redes sociales: rutinas de ejercicio, dietas, productos, consejos de «expertos». Parte de ese contenido es útil y parte es engañoso, pero cuesta distinguirlas.", "Además de informar, las redes influyen en lo que se considera normal o deseable, y eso casi nunca se analiza con datos."], "desarrollar": ["Elige tres tipos de contenido de salud o bienestar, junta unas veinte publicaciones públicas de cada tipo sin registrar a las personas, y clasifícalas por tema, tono y si citan una fuente.", "Haz una encuesta anónima a unas pocas personas sobre qué sigue, qué le sirve y qué le genera dudas, y resume qué contenidos parecen ayudar y cuáles confundir, con ejemplos generales."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo cambia la percepción entre personas de distintas edades."}, {"titulo": "Otro formato", "aporta": "resume los hallazgos en una guía de señales de alerta en contenido de salud."}, {"titulo": "Un paso más", "aporta": "propón cinco preguntas que alguien debería hacerse antes de seguir un consejo visto en redes."}], "objetivos": ["Clasificar publicaciones de forma ordenada.", "Reconocer características de contenido útil y engañoso.", "Recoger percepciones de forma anónima.", "Resumir hallazgos con cuidado."], "habilidades": ["Análisis de contenido.", "Encuestas.", "Análisis básico de datos.", "Pensamiento crítico."], "herramientas": ["Hoja de cálculo.", "Un formulario anónimo.", "Capturas de publicaciones públicas sin datos personales."], "lineamientos": ["No cites ni señales a cuentas o personas concretas: trabaja con ejemplos generales o descritos sin nombres.", "No evalúes la salud ni el estado emocional de nadie y no promuevas ni critiques dietas o rutinas concretas."], "otroSector": "El mismo método sirve para analizar el contenido sobre finanzas, educación, política o consumo en cualquier plataforma."}$g18sld$::jsonb,5),
('una-herramienta-para-ordenar-los-recursos-de-bienestar-de-una-comunidad','sociedad',array['salud','tecnologia']::text[],'Una herramienta para ordenar los recursos de bienestar de una comunidad','Reúne en un solo lugar los servicios y actividades de bienestar de una comunidad, como centros de salud, grupos de apoyo, talleres o programas gratuitos, y hazlos fáciles de encontrar.','Prototipo','~25 h',25,array['Recursos comunitarios','Bienestar']::text[],array['crear','resolver']::text[],'publicos',NULL,'ingenieria de sistemas ingenieria de software trabajo social sociologia administracion comunicaciones psicologia enfermeria busqueda y verificacion de informacion. diseno de informacion. organizacion de datos. pruebas con usuarios. hoja de calculo. un editor de paginas web o de documentos. un formulario de prueba.',$g19sld${"id": "una-herramienta-para-ordenar-los-recursos-de-bienestar-de-una-comunidad", "area": "sociedad", "areas2": ["salud", "tecnologia"], "titulo": "Una herramienta para ordenar los recursos de bienestar de una comunidad", "resumen": "Reúne en un solo lugar los servicios y actividades de bienestar de una comunidad, como centros de salud, grupos de apoyo, talleres o programas gratuitos, y hazlos fáciles de encontrar.", "tipo": "Prototipo", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Recursos comunitarios", "Bienestar"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Trabajo Social", "Sociología", "Administración", "Comunicaciones", "Psicología", "Enfermería"], "problema": ["Muchas comunidades tienen recursos de bienestar, desde actividades en un centro comunitario hasta programas gratuitos, pero están dispersos en publicaciones, carteles y llamadas. Quien más los necesita suele ser quien menos los encuentra.", "Cuando la información está desactualizada o incompleta, la gente deja de buscarla."], "desarrollar": ["Reúne información pública de diez a quince recursos de tu zona y registra de cada uno qué ofrece, a quién va dirigido, cómo acceder, horario y si cuesta, con fecha de revisión.", "Organízalos en una página o un directorio sencillo con búsqueda por tema y zona, y pide a dos personas que busquen algo concreto para ver si lo encuentran con facilidad."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "revisa qué grupos de personas quedan sin recursos disponibles."}, {"titulo": "Otro formato", "aporta": "conviértelo en un directorio impreso de una página para repartir en un centro comunitario."}, {"titulo": "Un paso más", "aporta": "diseña cómo mantenerlo actualizado, con una persona responsable y una fecha de revisión."}], "objetivos": ["Reunir información verificable de recursos de la comunidad.", "Organizarla con criterios claros.", "Construir un directorio fácil de usar.", "Probarlo con personas."], "habilidades": ["Búsqueda y verificación de información.", "Diseño de información.", "Organización de datos.", "Pruebas con usuarios."], "herramientas": ["Hoja de cálculo.", "Un editor de páginas web o de documentos.", "Un formulario de prueba."], "lineamientos": ["Verifica cada recurso en su fuente oficial y anota la fecha: la información de servicios cambia.", "No incluyas servicios de salud como recomendaciones personales ni datos de personas, solo información pública de cada recurso."], "otroSector": "Sirve para organizar recursos de empleo, de estudio, de cultura, de ayuda legal o de apoyo a migrantes."}$g19sld$::jsonb,6),
('que-barreras-encuentran-las-personas-con-discapacidad-para-recibir-atencion','sociedad',array['salud','ciudades']::text[],'¿Qué barreras encuentran las personas con discapacidad para recibir atención?','Revisa informes y testimonios públicos para identificar las barreras físicas, de comunicación y de información que enfrentan las personas con discapacidad al buscar atención, y propón ajustes concretos.','Investigación','~25 h',25,array['Inclusión','Acceso']::text[],array['investigar','resolver']::text[],'publicos',NULL,'trabajo social sociologia derecho arquitectura psicologia educacion ingenieria de sistemas medicina investigacion de fuentes. analisis de accesibilidad. redaccion clara. empatia y trato respetuoso. informes publicos y organizaciones especializadas. hoja de calculo. un editor de documentos.',$g20sld${"id": "que-barreras-encuentran-las-personas-con-discapacidad-para-recibir-atencion", "area": "sociedad", "areas2": ["salud", "ciudades"], "titulo": "¿Qué barreras encuentran las personas con discapacidad para recibir atención?", "resumen": "Revisa informes y testimonios públicos para identificar las barreras físicas, de comunicación y de información que enfrentan las personas con discapacidad al buscar atención, y propón ajustes concretos.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Inclusión", "Acceso"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Trabajo Social", "Sociología", "Derecho", "Arquitectura", "Psicología", "Educación", "Ingeniería de Sistemas", "Medicina"], "problema": ["Una persona con discapacidad puede encontrar barreras desde antes de llegar a un servicio: transporte, entradas con escalones, información que no está en formatos accesibles o personal que no sabe comunicarse con ella.", "Con frecuencia las soluciones se diseñan sin consultarlas, y por eso pasan por alto lo que más importa."], "desarrollar": ["Reúne informes de organismos públicos y de organizaciones de personas con discapacidad y clasifica las barreras en físicas, de comunicación, de información y de trato, con ejemplos generales.", "Elige un servicio, real o ficticio, y revisa qué barreras tendría en cada categoría, propón tres ajustes concretos y explica a quién beneficiarían, además de a quienes viven con discapacidad."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara las barreras entre distintos tipos de discapacidad, como motriz, visual o auditiva."}, {"titulo": "Otro formato", "aporta": "prepara una lista de revisión de accesibilidad para un servicio."}, {"titulo": "Un paso más", "aporta": "diseña materiales de información en un formato accesible, como lectura fácil o con descripción de imágenes."}], "objetivos": ["Reunir información de fuentes confiables.", "Clasificar barreras con criterio.", "Evaluar un servicio con esa lista.", "Proponer ajustes concretos."], "habilidades": ["Investigación de fuentes.", "Análisis de accesibilidad.", "Redacción clara.", "Empatía y trato respetuoso."], "herramientas": ["Informes públicos y organizaciones especializadas.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Usa lenguaje respetuoso, como «persona con discapacidad», y consulta fuentes hechas por las propias personas o sus organizaciones; la idea es trabajar con ellas, no hablar por ellas.", "No entrevistes a personas con discapacidad sin su consentimiento y sin un propósito claro, ni uses sus fotos o historias sin permiso."], "otroSector": "Sirve para evaluar la accesibilidad de un edificio, un sitio web, un transporte o un trámite público."}$g20sld$::jsonb,7),
('como-influye-el-aislamiento-social-en-el-bienestar','sociedad',array['salud','educacion']::text[],'¿Cómo influye el aislamiento social en el bienestar?','Estudia con informes públicos qué se sabe sobre cómo la soledad y el aislamiento se relacionan con el bienestar, y diseña una propuesta sencilla para generar encuentros en un grupo.','Investigación','~25 h',25,array['Vínculos','Bienestar']::text[],array['investigar','resolver']::text[],'publicos',NULL,'psicologia sociologia trabajo social educacion comunicaciones estadistica medicina enfermeria investigacion de fuentes. sintesis de informacion. diseno de actividades. redaccion clara. informes y estudios publicos. un editor de documentos. hoja de calculo.',$g21sld${"id": "como-influye-el-aislamiento-social-en-el-bienestar", "area": "sociedad", "areas2": ["salud", "educacion"], "titulo": "¿Cómo influye el aislamiento social en el bienestar?", "resumen": "Estudia con informes públicos qué se sabe sobre cómo la soledad y el aislamiento se relacionan con el bienestar, y diseña una propuesta sencilla para generar encuentros en un grupo.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Vínculos", "Bienestar"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Psicología", "Sociología", "Trabajo Social", "Educación", "Comunicaciones", "Estadística", "Medicina", "Enfermería"], "problema": ["Sentirse solo o aislado es frecuente en distintas etapas de la vida, como estudiar lejos de casa, mudarse, jubilarse o vivir solo, y se relaciona con cómo nos sentimos. Pero rara vez se habla de ello de forma ordenada.", "Se suele creer que es un problema personal, cuando también depende de los espacios y oportunidades que existen para encontrarse con otros."], "desarrollar": ["Revisa estudios e informes públicos sobre aislamiento social y resume en una página qué se sabe, para quién es más frecuente y qué ayuda, citando fuentes y sin entrar en casos personales.", "Diseña una actividad o espacio de encuentro para un grupo concreto, como estudiantes que viven solos, con una descripción de a quién va dirigido, qué se haría y cómo se sabría si funciona."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara los factores que aparecen en distintas etapas de la vida, como juventud y vejez."}, {"titulo": "Otro formato", "aporta": "convierte los hallazgos en un folleto de recursos para encontrarse con otras personas."}, {"titulo": "Un paso más", "aporta": "propón cómo medir, de manera anónima, si los participantes sienten mayor conexión."}], "objetivos": ["Reunir y resumir información de fuentes confiables.", "Identificar factores y grupos más expuestos.", "Diseñar una actividad de encuentro.", "Plantear cómo evaluarla."], "habilidades": ["Investigación de fuentes.", "Síntesis de información.", "Diseño de actividades.", "Redacción clara."], "herramientas": ["Informes y estudios públicos.", "Un editor de documentos.", "Hoja de cálculo."], "lineamientos": ["No pidas ni registres experiencias personales de soledad o malestar; trabaja con fuentes públicas y con casos generales.", "Si alguien comparte que está pasando por un mal momento, sugiérele hablar con una persona de confianza o con un servicio de apoyo; no intentes aconsejarle ni evaluarlo."], "otroSector": "Sirve para diseñar actividades que integren a un grupo: migrantes nuevos, equipos remotos o personas mayores en un centro comunitario."}$g21sld$::jsonb,8),
('una-guia-visual-para-explicar-una-enfermedad-o-un-tratamiento-con-palabras','arte',array['salud','educacion']::text[],'Una guía visual para explicar una enfermedad o un tratamiento con palabras sencillas','Convierte información de salud difícil en una guía visual clara, con palabras sencillas e imágenes, que cualquier persona pueda entender a la primera.','Diseño','~20 h',20,array['Infografía','Comunicación']::text[],array['crear','resolver']::text[],'publicos',NULL,'diseno grafico comunicaciones publicidad educacion enfermeria medicina nutricion ingenieria de sistemas diseno de informacion. escritura clara. pruebas con lectores. ilustracion o composicion visual. un editor de diseno o de presentaciones. guias oficiales de salud. una hoja para registrar lo que entendieron los lectores.',$g22sld${"id": "una-guia-visual-para-explicar-una-enfermedad-o-un-tratamiento-con-palabras", "area": "arte", "areas2": ["salud", "educacion"], "titulo": "Una guía visual para explicar una enfermedad o un tratamiento con palabras sencillas", "resumen": "Convierte información de salud difícil en una guía visual clara, con palabras sencillas e imágenes, que cualquier persona pueda entender a la primera.", "tipo": "Diseño", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Infografía", "Comunicación"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Diseño Gráfico", "Comunicaciones", "Publicidad", "Educación", "Enfermería", "Medicina", "Nutrición", "Ingeniería de Sistemas"], "problema": ["La información sobre enfermedades y tratamientos suele estar escrita con términos técnicos y en bloques de texto. Quien la recibe, a veces en un momento de preocupación, se queda con dudas o con una idea equivocada.", "Una buena explicación visual no sustituye a un profesional, pero ayuda a entender mejor y a hacer mejores preguntas."], "desarrollar": ["Elige un tema general y de uso común, como cómo se usa un termómetro o qué es la hipertensión, y busca una fuente oficial. Reescribe el contenido en frases cortas, sin tecnicismos, y decide qué imágenes lo explicarían mejor.", "Diseña la guía en una o dos páginas, pide a tres personas que no sean de salud que la lean y cuenten con sus palabras qué entendieron, y ajústala según lo que no quedó claro."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "adapta la guía a otro público, como niños o personas mayores."}, {"titulo": "Otro formato", "aporta": "conviértela en una secuencia de imágenes cortas o en un video breve."}, {"titulo": "Un paso más", "aporta": "agrega una versión para personas con baja visión o en lectura fácil."}], "objetivos": ["Seleccionar información confiable y reescribirla.", "Diseñar explicaciones visuales claras.", "Probarlas con lectores.", "Mejorar el diseño a partir de lo que se entiende."], "habilidades": ["Diseño de información.", "Escritura clara.", "Pruebas con lectores.", "Ilustración o composición visual."], "herramientas": ["Un editor de diseño o de presentaciones.", "Guías oficiales de salud.", "Una hoja para registrar lo que entendieron los lectores."], "lineamientos": ["Basa el contenido en fuentes oficiales y cítalas; no incluyas dosis, diagnósticos ni indicaciones personales.", "Si la guía circulará fuera de clase, pide que un profesional de salud la revise antes."], "otroSector": "La misma técnica sirve para explicar trámites, contratos, instrucciones de un aparato o procesos legales."}$g22sld$::jsonb,1),
('un-espacio-de-descanso-que-ayude-a-desconectarse','arte',array['salud','ciudades']::text[],'Un espacio de descanso que ayude a desconectarse','Diseña un rincón de descanso para un espacio real, como un aula, una sala de espera o una oficina, y comprueba con pruebas sencillas qué elementos ayudan a desconectarse y cuáles no.','Diseño','~20 h',20,array['Diseño de espacios','Descanso']::text[],array['crear','resolver']::text[],'propios',NULL,'arquitectura diseno grafico ingenieria civil psicologia ingenieria industrial educacion medicina ingenieria ambiental observacion. diseno de espacios. dibujo de planos. presupuesto basico. una herramienta para dibujar planos o modelar en 3d. hoja de calculo para el presupuesto. papel y cartulina para una maqueta.',$g23sld${"id": "un-espacio-de-descanso-que-ayude-a-desconectarse", "area": "arte", "areas2": ["salud", "ciudades"], "titulo": "Un espacio de descanso que ayude a desconectarse", "resumen": "Diseña un rincón de descanso para un espacio real, como un aula, una sala de espera o una oficina, y comprueba con pruebas sencillas qué elementos ayudan a desconectarse y cuáles no.", "tipo": "Diseño", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Diseño de espacios", "Descanso"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Arquitectura", "Diseño Gráfico", "Ingeniería Civil", "Psicología", "Ingeniería Industrial", "Educación", "Medicina", "Ingeniería Ambiental"], "problema": ["En lugares donde pasamos muchas horas, como centros de estudio, oficinas o servicios de atención, casi nunca hay un sitio pensado para parar unos minutos sin ruido, pantallas ni interrupciones.", "Cuando existen, suelen ser un rincón con sillas sin criterio, que no invita a quedarse."], "desarrollar": ["Elige un espacio real con permiso y observa cómo se usan las pausas actuales: dónde se sienta la gente, qué hace, qué la interrumpe. Haz un plano y define qué necesitaría un rincón de descanso: luz, ruido, asientos, privacidad, naturaleza.", "Dibuja o modela una propuesta de bajo costo, pide a algunas personas que la comenten, y deja el diseño final con una lista de materiales y un costo estimado."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara qué necesita un espacio de descanso para estudiantes y para personal de trabajo."}, {"titulo": "Otro formato", "aporta": "haz una maqueta sencilla o un plano en 3D."}, {"titulo": "Un paso más", "aporta": "diseña una señalización que invite a usarlo sin imponer reglas."}], "objetivos": ["Observar cómo se usan las pausas en un espacio.", "Definir necesidades y criterios de diseño.", "Proponer un diseño de bajo costo.", "Recoger opiniones y mejorarlo."], "habilidades": ["Observación.", "Diseño de espacios.", "Dibujo de planos.", "Presupuesto básico."], "herramientas": ["Una herramienta para dibujar planos o modelar en 3D.", "Hoja de cálculo para el presupuesto.", "Papel y cartulina para una maqueta."], "lineamientos": ["Pide permiso antes de observar o fotografiar un espacio, no registres personas ni sus rostros y respeta las normas de seguridad del lugar.", "Presenta el espacio como un lugar de pausa y comodidad, no como un tratamiento ni una solución a problemas de salud."], "otroSector": "Sirve para diseñar espacios de lectura, de espera, de oración, de juego infantil o de reuniones informales."}$g23sld$::jsonb,2),
('como-reconocer-informacion-de-salud-confiable-en-internet','arte',array['salud','sociedad']::text[],'¿Cómo reconocer información de salud confiable en internet?','Prepara una guía con pasos sencillos para comprobar si un mensaje o una página de salud es confiable, probada con ejemplos reales y un público concreto.','Guía','~15 h',15,array['Información','Verificación']::text[],array['crear','resolver']::text[],'publicos',NULL,'comunicaciones diseno grafico educacion psicologia ingenieria de sistemas derecho medicina enfermeria pensamiento critico. verificacion de informacion. diseno de informacion. pruebas con usuarios. buscadores y sitios de verificacion. un editor de diseno. una hoja para registrar las pruebas.',$g24sld${"id": "como-reconocer-informacion-de-salud-confiable-en-internet", "area": "arte", "areas2": ["salud", "sociedad"], "titulo": "¿Cómo reconocer información de salud confiable en internet?", "resumen": "Prepara una guía con pasos sencillos para comprobar si un mensaje o una página de salud es confiable, probada con ejemplos reales y un público concreto.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Información", "Verificación"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Comunicaciones", "Diseño Gráfico", "Educación", "Psicología", "Ingeniería de Sistemas", "Derecho", "Medicina", "Enfermería"], "problema": ["Al buscar información de salud en internet o en mensajes reenviados, es difícil saber qué es confiable: hay páginas serias, publicidad disfrazada, consejos inventados y mensajes que parecen urgentes.", "Muchas personas confían en lo que reciben de alguien cercano, y por eso la información falsa viaja tan rápido."], "desarrollar": ["Reúne diez ejemplos de mensajes o páginas de salud, unos confiables y otros dudosos, sin usar nombres de personas, y detecta qué señales los distinguen: fuente, fecha, tono, promesas, pedidos de compartir.", "Con esas señales arma una guía de cinco preguntas fáciles de recordar, pruébala con tres personas que decidan si un ejemplo nuevo es confiable y ajústala según lo que no les resultó claro."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara las señales que sirven para detectar noticias falsas con las que sirven para información de salud."}, {"titulo": "Otro formato", "aporta": "conviértela en una tarjeta o un sticker para compartir por mensajería."}, {"titulo": "Un paso más", "aporta": "agrega una lista de fuentes confiables que sirvan como punto de partida para buscar."}], "objetivos": ["Reunir ejemplos confiables y dudosos.", "Identificar señales que los distinguen.", "Armar una guía breve y fácil de recordar.", "Probarla y mejorarla."], "habilidades": ["Pensamiento crítico.", "Verificación de información.", "Diseño de información.", "Pruebas con usuarios."], "herramientas": ["Buscadores y sitios de verificación.", "Un editor de diseño.", "Una hoja para registrar las pruebas."], "lineamientos": ["Usa ejemplos sin nombres de personas ni marcas que puedas afectar; describe el tipo de mensaje y lo que lo hace confiable o dudoso.", "La guía ayuda a evaluar información, no a decidir tratamientos: siempre sugiere consultar a un profesional de salud."], "otroSector": "La misma guía sirve para evaluar información de finanzas, de política, de educación o de ofertas en internet."}$g24sld$::jsonb,3),
('como-se-comunican-los-riesgos-de-salud-durante-una-emergencia','arte',array['salud','sociedad']::text[],'¿Cómo se comunican los riesgos de salud durante una emergencia?','Compara cómo informaron las autoridades y los medios durante una emergencia sanitaria o un desastre, y descubre qué mensajes se entendieron mejor y cuáles generaron confusión.','Análisis','~20 h',20,array['Comunicación de riesgos','Emergencias']::text[],array['investigar','resolver']::text[],'publicos',NULL,'comunicaciones diseno grafico publicidad sociologia enfermeria medicina estadistica ingenieria civil analisis de mensajes. comunicacion de riesgos. redaccion clara. diseno de informacion. archivos de comunicados y noticias. hoja de calculo. un editor de diseno.',$g25sld${"id": "como-se-comunican-los-riesgos-de-salud-durante-una-emergencia", "area": "arte", "areas2": ["salud", "sociedad"], "titulo": "¿Cómo se comunican los riesgos de salud durante una emergencia?", "resumen": "Compara cómo informaron las autoridades y los medios durante una emergencia sanitaria o un desastre, y descubre qué mensajes se entendieron mejor y cuáles generaron confusión.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Comunicación de riesgos", "Emergencias"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Comunicaciones", "Diseño Gráfico", "Publicidad", "Sociología", "Enfermería", "Medicina", "Estadística", "Ingeniería Civil"], "problema": ["En una emergencia, la forma de comunicar el riesgo puede cambiar lo que hace la gente: un mensaje claro ayuda a actuar y uno confuso genera pánico, desinterés o rumores.", "Aun así, casi nunca se revisa después qué se dijo, cómo y a quién, ni se aprende de lo que no funcionó."], "desarrollar": ["Elige una emergencia ocurrida, recopila comunicados, avisos y mensajes públicos de autoridades y medios, y ordénalos por fecha, canal y tipo de mensaje, sin usar contenido de personas particulares.", "Evalúa cada mensaje con criterios simples: claridad, qué pide hacer, a quién se dirige y qué podría confundir; resume qué se entendió bien y propón cómo mejorar tres mensajes."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo se comunicó la misma emergencia en distintos canales, como radio, redes o carteles."}, {"titulo": "Otro formato", "aporta": "rediseña uno de los mensajes más confusos con una versión clara."}, {"titulo": "Un paso más", "aporta": "prepara una plantilla de mensaje de alerta que cualquier institución pueda usar."}], "objetivos": ["Reunir mensajes públicos de una emergencia.", "Evaluarlos con criterios de claridad.", "Identificar lo que ayudó y lo que confundió.", "Proponer mejoras concretas."], "habilidades": ["Análisis de mensajes.", "Comunicación de riesgos.", "Redacción clara.", "Diseño de información."], "herramientas": ["Archivos de comunicados y noticias.", "Hoja de cálculo.", "Un editor de diseño."], "lineamientos": ["Usa solo información pública y cita las fuentes; no incluyas fotos de víctimas ni contenido sensible.", "Evalúa los mensajes, no a las personas o instituciones que los emitieron, y reconoce que decidir en una emergencia es difícil."], "otroSector": "Sirve para analizar la comunicación de una empresa en una crisis, de un cambio de servicio o de una alerta de seguridad."}$g25sld$::jsonb,4)
